defmodule Sentinelix.Repo.Migrations.AddAutomaticLabelsToMonitors do
  use Ecto.Migration

  # Automatic labels (see Sentinelix.Monitoring.AutoLabels) are derived from
  # the monitor's type and settings on save and stored in `auto_labels`.
  # `all_labels` is the union of user and automatic labels, generated by the
  # database, so selectors query both with the same operators and index.
  #
  # Existing monitors get their automatic labels here; the SQL mirrors
  # AutoLabels.derive/2 for the hosts monitors can have (a later save
  # derives them again in Elixir). User labels with a reserved key (`type`,
  # `host`) are dropped when they equal the automatic label and renamed to
  # `user/<key>` otherwise.
  def up do
    alter table(:monitors) do
      add :auto_labels, :map, null: false, default: fragment("'{}'::jsonb")
    end

    execute("""
    UPDATE monitors AS m
       SET auto_labels = jsonb_strip_nulls(jsonb_build_object('type', m.type, 'host', h.host))
      FROM (SELECT id,
                   CASE WHEN host ~ '^[a-z0-9_.:/@-]{1,255}$' THEN host END AS host
              FROM (SELECT id,
                           rtrim(lower(CASE
                             WHEN target LIKE '[%' THEN substring(target from '^\\[([^]]*)')
                             WHEN target ~ '^[^:]*:[^:]*$' THEN split_part(target, ':', 1)
                             ELSE target
                           END), '.') AS host
                      FROM (SELECT id,
                                   btrim(CASE
                                     WHEN type IN ('http', 'keyword') THEN
                                       substring(settings->>'url'
                                                 from '^[A-Za-z][A-Za-z0-9+.-]*://(?:[^/?#@]*@)?([^/?#]*)')
                                     WHEN type IN ('tcp', 'ping', 'dns', 'cert', 'postgres') THEN
                                       settings->>'host'
                                   END) AS target
                              FROM monitors) AS targets) AS hosts) AS h
     WHERE h.id = m.id
    """)

    execute("""
    UPDATE monitors SET labels = (
      SELECT COALESCE(
               jsonb_object_agg(
                 CASE WHEN key IN ('type', 'host') THEN 'user/' || key ELSE key END,
                 value),
               '{}'::jsonb)
        FROM jsonb_each(labels)
       WHERE key NOT IN ('type', 'host') OR auto_labels->key IS DISTINCT FROM value)
     WHERE labels ?| ARRAY['type', 'host']
    """)

    execute("""
    ALTER TABLE monitors
      ADD COLUMN all_labels jsonb GENERATED ALWAYS AS (labels || auto_labels) STORED
    """)

    # Selectors query `all_labels`; the index on `labels` isn't used anymore.
    drop index(:monitors, [:labels])
    create index(:monitors, [:all_labels], using: :gin)
  end

  # Renamed `user/<key>` labels keep their new key.
  def down do
    drop index(:monitors, [:all_labels])
    create index(:monitors, [:labels], using: :gin)

    alter table(:monitors) do
      remove :all_labels
      remove :auto_labels
    end
  end
end
